    roomId,
    modelId,
    message,
    context = {},
    meta = {},
    signal,
    onEvent,
  }: LegacyCodeStreamRequest): Promise<void> {
    const response = await fetch(`${API_BASE_URL}/legacy/code/rooms/${encodeURIComponent(roomId)}/continue`, {
      method: 'POST',
      credentials: 'same-origin',
      signal,
      headers: streamingHeaders(),
      body: JSON.stringify({ modelId, message, context, meta }),
    });
    if (!response.ok) throw await parseError(response);
    let streamedError: ApiError | null = null;
    await parseServerSentEvents(response, (event) => {
      onEvent(event);
      if (event.event !== 'error') return;
      let details: unknown = event.data;
      try { details = JSON.parse(event.data) as unknown; } catch { /* Preserve plain-text event data. */ }
      const message = details && typeof details === 'object' && 'message' in details
        ? String((details as { message: unknown }).message)
        : String(event.data || 'AI 코드 응답 스트림이 중단되었습니다.');
      streamedError = new ApiError(message, 502, details);
    });
    if (streamedError) throw streamedError;
  },
