      ...(conversationId ? { conversationId } : {}),
      ...(projectId ? { projectId } : {}),
      ...(execute !== undefined ? { execute } : {}),
      ...(approvalRequestId ? { approvalRequestId } : {}),
    };
    const response = await fetch(`${API_BASE_URL}/agent/runs/stream`, {
      method: 'POST',
      credentials: 'same-origin',
      signal,
      headers: streamingHeaders(),
      body: JSON.stringify(payload),
    });
    if (!response.ok) throw await parseError(response);
    await streamAgentResponse(response, onEvent);
  },
  agentRun<T = Record<string, unknown>>(runId: string): Promise<T> {
    return request<T>(`/agent/runs/${encodeURIComponent(runId)}`);
  },
  askOriginal(payload: LegacyAskOriginalRequest): Promise<LegacyAskOriginalResponse> {
