  it('decodes server-sent streaming deltas in order', async () => {
    const encoder = new TextEncoder();
    const cancel = vi.fn();
    const body = new ReadableStream({
      start(controller) {
        controller.enqueue(encoder.encode('data: {"delta":"안녕"}\n\n'));
        controller.enqueue(encoder.encode('data: {"content":"하세요"}\n\ndata: [DONE]\n\n'));
        controller.close();
      },
      cancel,
    });
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(new Response(body, {
      status: 200,
      headers: { 'Content-Type': 'text/event-stream' },
    }));
    const deltas: string[] = [];

    await apiClient.streamChat({ prompt: '인사', onDelta: (value) => deltas.push(value) });

    expect(deltas).toEqual(['안녕', '하세요']);
    expect(body.locked).toBe(false);
    expect(cancel).not.toHaveBeenCalled();
  });

  it('cancels and unlocks an open chat stream while preserving the server error', async () => {
    const details = { type: 'error', code: 'provider_failed', message: 'provider stopped' };
    const cancel = vi.fn();
    let source!: ReadableStreamDefaultController<Uint8Array>;
    const body = new ReadableStream<Uint8Array>({
      start(controller) {
        source = controller;
        controller.enqueue(new TextEncoder().encode(`event: error\ndata: ${JSON.stringify(details)}\n\n`));
      },
      cancel,
    });
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(new Response(body));

    try {
      const result = apiClient.streamChat({ prompt: '인사', onDelta: () => undefined });
      await expect(result).rejects.toBeInstanceOf(ApiError);
      await expect(result).rejects.toMatchObject({ status: 502, message: 'provider stopped', details });
      expect(cancel).toHaveBeenCalledTimes(1);
      expect(body.locked).toBe(false);
    } finally {
      // Clean up after assertions so the test cannot hide missing parser cleanup.
      source.error(new Error('test cleanup'));
    }
  });

  it.each([
    { callback: 'onDelta', cancelRejects: false },
    { callback: 'onEvent', cancelRejects: false },
    { callback: 'onDelta', cancelRejects: true },
    { callback: 'onEvent', cancelRejects: true },
  ] as const)('cleans up after $callback throws (cancel rejects: $cancelRejects)', async ({ callback, cancelRejects }) => {
    const sentinel = new Error('callback failed');
    const cancel = vi.fn(() => cancelRejects ? Promise.reject(new Error('cancel failed')) : Promise.resolve());
    let source!: ReadableStreamDefaultController<Uint8Array>;
    const body = new ReadableStream<Uint8Array>({
      start(controller) {
        source = controller;
        controller.enqueue(new TextEncoder().encode('data: {"delta":"안녕"}\n\n'));
      },
      cancel,
    });
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(new Response(body));
    const onDelta = vi.fn(() => { if (callback === 'onDelta') throw sentinel; });
    const onEvent = vi.fn(() => { if (callback === 'onEvent') throw sentinel; });

    try {
      await expect(apiClient.streamChat({ prompt: '인사', onDelta, onEvent })).rejects.toBe(sentinel);
      expect(onEvent).toHaveBeenCalledTimes(1);
      expect(onDelta).toHaveBeenCalledTimes(callback === 'onDelta' ? 1 : 0);
      expect(cancel).toHaveBeenCalledTimes(1);
      expect(body.locked).toBe(false);
    } finally {
      source.error(new Error('test cleanup'));
    }
  });

